// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public {
        c = new MONEY_BOX();
        c.SetMinSum(1 ether);
        c.SetLogFile(address(new Log()));
        c.Initialized();
    }

    function testFuzz_property(uint256 balanceBefore, uint256 collectAmt, uint256 lockTime) public {
        vm.assume(balanceBefore >= 1 ether && balanceBefore <= 1000 ether);
        vm.assume(collectAmt >= 1 && collectAmt <= balanceBefore);
        vm.assume(lockTime <= 365 days);

        address actor = makeAddr("actor");
        vm.deal(actor, balanceBefore);
        vm.prank(actor);
        c.Put{value: balanceBefore}(lockTime);

        vm.warp(block.timestamp + lockTime + 1);
        vm.prank(actor);
        c.Collect(collectAmt);

        ( , uint256 balAfter) = c.Acc(actor);
        assertTrue(balAfter == balanceBefore - collectAmt);
    }
}

contract Log {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }
    Message[] public History;
    Message LastMsg;
    function AddMessage(address _adr,uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}
